"""Evaluate frozen timing proxy decisions against subsequently captured labels."""
import json
from pathlib import Path
from pre_route_endpoints import sha
out=Path('experiments/frisc_bound_proxy_evaluation_v2_2026-10-05');decision_path=Path('experiments/frisc_bound_proxy_decision_v2_2026-10-05/decision.json');native=Path('experiments/frisc_timing_native_labels_v2_2026-10-05');bg=Path('experiments/frisc_timing_backgrounds_v2_2026-10-05')
if out.exists():raise ValueError('fresh output required')
d=json.loads(decision_path.read_text());n=json.loads((native/'receipt.json').read_text());p=json.loads((native/'protocol.json').read_text());a=json.loads((native/'native_labels_audit.json').read_text());b=json.loads((bg/'receipt.json').read_text());ba=json.loads((bg/'independent_audit.json').read_text());assert p['decision_sha256']==sha(decision_path);assert a['receipt_sha256']==sha(native/'receipt.json') and a['all_nine_native_runs_authenticated'];assert ba['receipt_sha256']==sha(bg/'receipt.json');assert all(sha(f)==h for f,h in d['input_sha256'].items())
truth={x['candidate_id']:x for x in n['rows']};assert set(truth)==set(range(9));base=truth[0];rows=[]
for arm in ('on','off'):
 cid=d[arm+'_candidate'];actual=truth[cid];accept=actual['wirelength']<base['wirelength'] and actual['cpd_ns']<=base['cpd_ns'];rows.append({'arm':arm,'selected_candidate':cid,'native_wirelength_delta':actual['wirelength']-base['wirelength'],'native_cpd_delta_ns':actual['cpd_ns']-base['cpd_ns'],'accepted':accept,'final_candidate':cid if accept else 0,'final_wirelength':actual['wirelength'] if accept else base['wirelength'],'selected_native_launcher_wall_s':actual['launcher_wall_s']})
feasible=[c for c in truth if truth[c]['wirelength']<base['wirelength'] and truth[c]['cpd_ns']<=base['cpd_ns']];false_reject=[x['candidate_id'] for x in d['rows'] if not x['proxy_gate'] and x['candidate_id'] in feasible];missed_timing=[x['candidate_id'] for x in d['rows'] if x['proxy_gate'] and truth[x['candidate_id']]['cpd_ns']>base['cpd_ns']]
receipt={'scope':'new disjoint candidate prospective on/off proxy trial on previously explored frisc; labels follow frozen decision','arms':rows,'native_acceptable_improvement_ids':feasible,'proxy_rejected_native_acceptable_ids':false_reject,'proxy_admitted_native_timing_regression_ids':missed_timing,'on_minus_off_final_wirelength':rows[0]['final_wirelength']-rows[1]['final_wirelength'],'background_full_wall_s':b['full_wall_s'],'bound_proxy_prepare_evaluate_wall_s':d['wall_s'],'shared_native_evaluation':d['on_candidate']==d['off_candidate'],'source_evidence_sha256':{str(f):sha(f) for f in (decision_path,native/'receipt.json',native/'native_labels_audit.json',bg/'receipt.json',bg/'independent_audit.json')},'evaluator_sha256':sha(__file__),'limitations':['same design and single seed','same selected candidate shares native evaluation; not independent paired runtime arms','background/context/candidate initial generation reuse or costs must be charged separately','observed proxy does not guarantee CPD','no design-family or FPGA performance conclusion']};out.mkdir();(out/'source.py').write_text(Path(__file__).read_text());(out/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt))
